async function main() {
  const page = await figma.getNodeByIdAsync("0:1");
  if (!page) {
    console.log("Page 0:1 not found");
    return;
  }

  // Find all text nodes in 0:1
  const texts = page.findAll(node => node.type === "TEXT");
  console.log(`Found ${texts.length} text nodes in Page 0:1`);

  // Sort them by their position (Y then X) to make reading coherent
  texts.sort((a, b) => {
    const ay = a.absoluteTransform[1][2];
    const by = b.absoluteTransform[1][2];
    if (Math.abs(ay - by) < 10) {
      return a.absoluteTransform[0][2] - b.absoluteTransform[0][2];
    }
    return ay - by;
  });

  for (const t of texts) {
    console.log(`[${t.name}]: ${t.characters.substring(0, 500)}`);
  }
}
