async function main() {
  const page = figma.getNodeById("0:1");
  if (!page) {
    return "Page 0:1 not found";
  }

  const texts = page.findAll(node => node.type === "TEXT");
  texts.sort((a, b) => {
    const ay = a.absoluteRenderBounds ? a.absoluteRenderBounds.y : a.y;
    const by = b.absoluteRenderBounds ? b.absoluteRenderBounds.y : b.y;
    if (Math.abs(ay - by) < 15) {
      const ax = a.absoluteRenderBounds ? a.absoluteRenderBounds.x : a.x;
      const bx = b.absoluteRenderBounds ? b.absoluteRenderBounds.x : b.x;
      return ax - bx;
    }
    return ay - by;
  });

  let result = `Found ${texts.length} text nodes in 00 · Start Here:\n`;
  for (const t of texts) {
    result += `\n--- [Node ID: ${t.id}, Name: ${t.name}] ---\n${t.characters}\n`;
  }
  return result;
}
