async function main() {
  const wsPage = figma.getNodeById("3:2");
  if (!wsPage) return;

  // Clear any existing temp text nodes
  const oldDump = wsPage.findOne(n => n.name === "component_map_dump");
  if (oldDump) oldDump.remove();

  // Helper to load fonts
  async function loadFonts() {
    await figma.loadFontAsync({ family: "Quicksand", style: "Bold" });
    await figma.loadFontAsync({ family: "Nunito", style: "Regular" });
    await figma.loadFontAsync({ family: "Nunito", style: "Semi Bold" });
    await figma.loadFontAsync({ family: "Nunito", style: "Bold" });
  }
  await loadFonts();

  // Find component helper
  function getComp(name) {
    const comp = figma.root.findOne(n => n.type === "COMPONENT" && n.name === name);
    if (!comp) {
      // Search inside component sets as well
      const compSet = figma.root.findOne(n => n.type === "COMPONENT_SET" && n.name === name);
      if (compSet) return compSet.defaultVariant;
    }
    return comp;
  }

  // Let's create a test container to see if we can find components
  const testInfo = [];
  ["Button", "Text Field", "Status Bar", "Home Indicator", "Logo_MindfulMentor", "Mood_Calm", "Icon_Back"].forEach(name => {
    const c = getComp(name);
    testInfo.push(`${name}: ${c ? "Found" : "Not Found"}`);
  });

  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  const text = figma.createText();
  text.name = "component_map_dump";
  text.characters = testInfo.join("\n");
  wsPage.appendChild(text);
}
