async function main() {
  const wsPage = figma.getNodeById("3:2");
  if (!wsPage) return;

  // Clear any existing frames on 3:2
  const existingFrames = wsPage.children.filter(n => n.type === "FRAME");
  existingFrames.forEach(f => f.remove());

  const frameNames = [
    "01_Check_In", "02_Stress_Sources", "03_Today", "04_Focus_Session",
    "05_Reflect", "06_Growth_Insights", "07_Your_Routine", "08_Campus_Support",
    "09_Exam_Mode", "10_Immediate_Support", "11_Your_Journey", "12_Micro_Exercises"
  ];

  // Find Status Bar & Home Indicator
  const statusBar = figma.root.findOne(n => n.type === "COMPONENT" && n.name === "Status Bar");
  const homeIndicator = figma.root.findOne(n => n.type === "COMPONENT" && n.name === "Home Indicator");

  const colCount = 4;
  const colWidth = 390;
  const rowHeight = 844;
  const gap = 100;

  for (let i = 0; i < frameNames.length; i++) {
    const name = frameNames[i];
    const frame = figma.createFrame();
    frame.name = name;

    // Position
    const col = i % colCount;
    const row = Math.floor(i / colCount);
    frame.x = col * (colWidth + gap);
    frame.y = row * (rowHeight + gap);
    frame.resize(colWidth, rowHeight);

    // Background color: Soft off-white/sage `#FAFCFB`
    frame.fills = [{
      type: "SOLID",
      color: { r: 0.98, g: 0.988, b: 0.984 }
    }];

    wsPage.appendChild(frame);

    // Add Status Bar at top
    if (statusBar) {
      const inst = statusBar.createInstance();
      inst.x = 0;
      inst.y = 0;
      frame.appendChild(inst);
    }

    // Add Home Indicator at bottom
    if (homeIndicator) {
      const inst = homeIndicator.createInstance();
      inst.x = 0;
      inst.y = 844 - 34;
      frame.appendChild(inst);
    }
  }
}
