async function main() {
  const wsPage = figma.getNodeById("3:2");
  if (!wsPage) return;

  function getFrame(name) {
    return wsPage.children.find(c => c.type === "FRAME" && c.name === name);
  }

  const f1 = getFrame("01_Check_In");
  const f2 = getFrame("02_Stress_Sources");
  const f3 = getFrame("03_Today");
  const f4 = getFrame("04_Focus_Session");
  const f5 = getFrame("05_Reflect");
  const f6 = getFrame("06_Growth_Insights");
  const f7 = getFrame("07_Your_Routine");
  const f8 = getFrame("08_Campus_Support");
  const f9 = getFrame("09_Exam_Mode");
  const f10 = getFrame("10_Immediate_Support");
  const f11 = getFrame("11_Your_Journey");
  const f12 = getFrame("12_Micro_Exercises");

  function link(source, target) {
    if (!source || !target) return;
    source.reactions = [{
      action: {
        type: "NAVIGATE",
        destinationId: target.id,
        navigation: "NAVIGATE",
        transition: { type: "SMART_ANIMATE", duration: 300, easing: "EASE_IN_AND_OUT" }
      },
      trigger: { type: "ON_CLICK" }
    }];
  }

  // ==========================================
  // 01_Check_In Links
  // ==========================================
  if (f1 && f2 && f3) {
    // Any mood card -> 02_Stress_Sources
    ["MoodCard_Calm", "MoodCard_Stressed", "MoodCard_Anxious", "MoodCard_Exhausted"].forEach(name => {
      const card = f1.findOne(n => n.name === name);
      if (card) link(card, f2);
    });

    // Skip check-in for now -> 03_Today
    const skip = f1.findOne(n => n.type === "TEXT" && n.characters === "Skip check-in for now");
    if (skip) link(skip, f3);
  }

  // ==========================================
  // 02_Stress_Sources Links
  // ==========================================
  if (f2 && f1 && f3) {
    // Back -> 01_Check_In
    const back = f2.findOne(n => n.name.startsWith("Icon_Back") || n.name === "Icon_Back");
    if (back) link(back, f1);

    // Skip -> 03_Today
    const skip = f2.findOne(n => n.type === "TEXT" && n.characters === "Skip");
    if (skip) link(skip, f3);

    // Continue Button -> 03_Today
    const btn = f2.findOne(n => n.name.startsWith("Button") || n.name === "Button");
    if (btn) link(btn, f3);
  }

  // ==========================================
  // 03_Today Links
  // ==========================================
  if (f3) {
    // Pre-Exam Calm card -> 04_Focus_Session
    const recCard = f3.findOne(n => n.name === "RecCard");
    if (recCard && f4) link(recCard, f4);

    // View Insights -> 06_Growth_Insights
    const viewIns = f3.findOne(n => n.type === "TEXT" && n.characters === "View Insights");
    if (viewIns && f6) link(viewIns, f6);

    // Tab bar wiring:
    const tabBar = f3.findOne(n => n.name === "TabBar");
    if (tabBar) {
      // Index 1 (Explore) -> 12_Micro_Exercises
      if (f12) link(tabBar.children[1], f12);
      // Index 2 (Center Action) -> 10_Immediate_Support
      if (f10) link(tabBar.children[2], f10);
      // Index 3 (Journal) -> 11_Your_Journey
      if (f11) link(tabBar.children[3], f11);
      // Index 4 (Profile) -> 07_Your_Routine
      if (f7) link(tabBar.children[4], f7);
    }
  }

  // ==========================================
  // 04_Focus_Session Links
  // ==========================================
  if (f4 && f5) {
    // Close -> 05_Reflect
    const close = f4.findOne(n => n.name.startsWith("Icon_Close") || n.name === "Icon_Close");
    if (close) link(close, f5);
  }

  // ==========================================
  // 05_Reflect Links
  // ==========================================
  if (f5 && f3) {
    // Yes, I feel better -> 03_Today
    const yesBtn = f5.findOne(n => n.name.startsWith("Button") || n.name === "Button");
    if (yesBtn) link(yesBtn, f3);

    // Skip for now -> 03_Today
    const skip = f5.findOne(n => n.type === "TEXT" && n.characters === "Skip for now");
    if (skip) link(skip, f3);

    // Close -> 03_Today
    const close = f5.findOne(n => n.name.startsWith("Icon_Close") || n.name === "Icon_Close");
    if (close) link(close, f3);
  }

  // ==========================================
  // 06_Growth_Insights Links
  // ==========================================
  if (f6 && f3) {
    // Back -> 03_Today
    const back = f6.findOne(n => n.name.startsWith("Icon_Back") || n.name === "Icon_Back");
    if (back) link(back, f3);
  }

  // ==========================================
  // 07_Your_Routine Links
  // ==========================================
  if (f7) {
    // Back -> 03_Today
    const back = f7.findOne(n => n.name.startsWith("Icon_Back") || n.name === "Icon_Back");
    if (back && f3) link(back, f3);

    // Switch Mode (within suggest banner or switch text) -> 09_Exam_Mode
    const banner = f7.findOne(n => n.name === "TabBar" ? false : (n.type === "TEXT" && n.characters === "Switch Mode"));
    if (banner && f9) link(banner, f9);
  }

  // ==========================================
  // 08_Campus_Support Links
  // ==========================================
  if (f8 && f10) {
    // Back -> 10_Immediate_Support
    const back = f8.findOne(n => n.name.startsWith("Icon_Back") || n.name === "Icon_Back");
    if (back) link(back, f10);
  }

  // ==========================================
  // 09_Exam_Mode Links
  // ==========================================
  if (f9) {
    // 2-Min Emergency Calm -> 10_Immediate_Support
    const emCalm = f9.findOne(n => n.type === "TEXT" && n.characters === "2-Min Emergency Calm");
    if (emCalm && f10) link(emCalm.parent, f10);

    // Quick Grounding -> 04_Focus_Session
    const qGround = f9.findOne(n => n.type === "TEXT" && n.characters === "Quick Grounding");
    if (qGround && f4) link(qGround.parent, f4);
  }

  // ==========================================
  // 10_Immediate_Support Links
  // ==========================================
  if (f10) {
    // Start Grounding -> 04_Focus_Session
    const stGround = f10.findOne(n => n.type === "TEXT" && n.characters === "Start Grounding");
    if (stGround && f4) link(stGround.parent, f4);

    // Campus Support tile -> 08_Campus_Support
    const csTile = f10.findOne(n => n.type === "TEXT" && n.characters === "Campus Support");
    if (csTile && f8) link(csTile.parent, f8);
  }

  // ==========================================
  // 12_Micro_Exercises Links
  // ==========================================
  if (f12 && f4) {
    // Overthinking Spiral card -> 04_Focus_Session
    const overthinkingText = f12.findOne(n => n.type === "TEXT" && n.characters === "Overthinking Spiral");
    if (overthinkingText) link(overthinkingText.parent, f4);
  }
}
main();

async function main() {
  const wsPage = figma.getNodeById("3:2");
  if (!wsPage) return;

  const frames = wsPage.children.filter(n => n.type === "FRAME");
  const details = frames.map(f => {
    return `- ${f.name} (ID: ${f.id}, Size: ${f.width}x${f.height}, Reactions: ${f.reactions ? f.reactions.length : 0})`;
  }).join("\n");

  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  const reportText = figma.createText();
  reportText.name = "final_verification_report";
  reportText.characters = `Workspace Verification Report:\n\n${details}`;
  wsPage.appendChild(reportText);
}
main();

